import{_ as o,l as i,o as e,c as l,v as t,p as s,x as r,d as n,i as D,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"CD-SEM 与散射测量","description":"","frontmatter":{"title":"CD-SEM 与散射测量","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/cd-sem-scatterometry.md","filePath":"litho/cd-sem-scatterometry.md","lastUpdated":1789023840000}'),d={name:"litho/cd-sem-scatterometry.md"};function C(h,a,c,m,S,A){const E=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="cd-sem-与散射测量" tabindex="-1">CD-SEM 与散射测量 <a class="header-anchor" href="#cd-sem-与散射测量" aria-label="Permalink to &quot;CD-SEM 与散射测量&quot;">​</a></h1><div class="epigraph"><p>工艺窗口的纵轴是 CD；扫描电镜给出局部形貌与粗糙度，散射测量给出光栅的平均剖面，两者量的不是同一个统计量。</p><footer>—— 据 Levinson 对 CD 计量的讨论，以及产线 CD-SEM / OCD 分工的公开表述整理</footer></div><p><a href="/litho/cdu-uniformity">上一课</a>（CD 均匀性 CDU）。在此之上，合格区画在曝光–散焦平面上，纵轴默认是「真 CD」。缺口是：真值没有直接读数——CD-SEM 有充电、收缩与边缘算法，光学散射测量（OCD）有模型误差。本课钉两种计量各回答什么。位置误差怎么量，留给<a href="/litho/overlay-marks">下一课</a>，不要在这里把套刻标记当 CD 垫。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Bossung 上每一个点都来自一次测量。SEM 俯视线条，用二次电子边缘判据估宽度，空间分辨率够看 LER，也够看缺陷和局部桥连。代价是慢、有电子束引起的胶收缩、充电使边缘漂移，算法阈值把「SEM CD」变成带偏置的量。</p><p>散射测量把宽带偏光打到周期光栅上，反演膜厚、CD、侧壁角。快，适合场内抽样和进机台反馈，给出的是光照光斑内的平均剖面，看不见单根线的毛边，也看不见非周期的随机缺孔。缺口因此是分工，不是选一个「更准」的冠军。</p><h3 id="窗口用均值-粗糙度用-sem" tabindex="-1">窗口用均值，粗糙度用 SEM <a class="header-anchor" href="#窗口用均值-粗糙度用-sem" aria-label="Permalink to &quot;窗口用均值，粗糙度用 SEM&quot;">​</a></h3><p>E–D 窗口通常切的是平均 CD。OCD 或 SEM 的场均值都可以喂窗口，但必须固定配方：同一套边缘定义、同一校准片。LWR、缺陷、局部 OPC 热点只能 SEM（或 e-beam review）。把 OCD 的漂亮均值写成「没有 LWR」，是把统计量偷换了。</p><p><span class="marginnote">胶上 SEM 与刻蚀后 SEM 不是同一条 Bossung。收缩、倒角、硬掩模偏置都会搬家。写窗口要声明量的是显影后还是刻蚀后。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>CD-SEM：设定加速电压、束流、帧平均与边缘算法，沿设计点取样。要报 LER 时必须声明滤波与空间频率。剂量矩阵上，电子收缩会让看起来「CD 随测量变细」，需用预剂量或低温、低电压策略，不能把收缩写进胶衬度。</p><p>OCD：在划片槽或专用计量垫上放满足周期假设的光栅，光谱拟合堆栈。模型要含材料色散和侧壁；换胶、换底层等于换模型。与 SEM 做相关，得到一个偏置，再把偏置当常数用——工艺漂了，相关要重做。</p><h3 id="进扫描机的反馈" tabindex="-1">进扫描机的反馈 <a class="header-anchor" href="#进扫描机的反馈" aria-label="Permalink to &quot;进扫描机的反馈&quot;">​</a></h3><p>平均 CD 反馈剂量，用 OCD 或 SEM 抽样都可以；进率决定能不能场级控制。形貌（侧壁角）更偏 OCD。热点与缺陷审查走 SEM。本课不展开 APC 软件，只要求窗口实验在矩阵上写明计量链。</p>',14)),(e(),s(p,null,{default:r(()=>[D(E,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20PW%5B%22E%E2%80%93D%20%E7%AA%97%E5%8F%A3%E9%9C%80%E8%A6%81%20CD%22%5D%20--%3E%20SEM%5B%22CD-SEM%3A%20%E5%B1%80%E9%83%A8%20%2F%20LER%20%2F%20%E7%BC%BA%E9%99%B7%22%5D%0A%20%20PW%20--%3E%20OCD%5B%22%E6%95%A3%E5%B0%84%E6%B5%8B%E9%87%8F%3A%20%E5%B9%B3%E5%9D%87%E5%89%96%E9%9D%A2%22%5D%0A%20%20SEM%20--%3E%20BIAS%5B%22%E7%AE%97%E6%B3%95%E4%B8%8E%E6%94%B6%E7%BC%A9%E5%81%8F%E7%BD%AE%22%5D%0A%20%20OCD%20--%3E%20MOD%5B%22%E5%85%89%E5%AD%A6%E6%A8%A1%E5%9E%8B%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20SEM%20--%3E%20OV%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E4%BD%8D%E7%BD%AE%E6%A0%87%E8%AE%B0%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>SEM 边缘是电子散射与充电的卷积，不是几何切面。同一物理宽度，胶种与形貌变了，二次电子拐点会移，CD 假漂。OCD 是远场衍射反问题，多解与材料色散误差表现为 CD 与侧壁角互换：一个变胖、一个变陡，光谱仍拟合。所以两种方法的符合要在稳定工艺上标定，而不是一次对准永远准。</p><p>上一课的重叠窗口若混用两种计量而不声明，交集会假性变窄或变宽。规定：一类图形固定一种量法做窗口，另一种做监护。</p><h3 id="与-opc-模拟器对齐定义" tabindex="-1">与 OPC 模拟器对齐定义 <a class="header-anchor" href="#与-opc-模拟器对齐定义" aria-label="Permalink to &quot;与 OPC 模拟器对齐定义&quot;">​</a></h3><p>OPC 验证常用 SEM 热点对照模拟 CD。若 SEM 边缘算法与模拟器输出的「阈值 CD」不是同一个切点，会把光学模型修歪。散射测量给出的平均截面更接近紧凑抗蚀剂模型，但看不见二维热点。闭环必须声明：哪一种 CD 进了哪一个模型，换胶或换 BARC 之后相关要重做。</p><p><span class="marginnote">不要把 scatterometry 理解成光学显微镜量线宽。它是衍射谱反演，对节距、材料色散和底层薄膜极敏感。叠层一变，库要重算。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不是 SEM 硬件课，不讲柱体像差。也不把散射测量写成可以替代套刻：光栅可以兼做套刻垫，但物理量是位置差，下一课才定义。EUV 缺孔统计必须 SEM/电镜审查，OCD 平均不到泊松尾。掩模上的 CD 计量（掩模 SEM、AIMS）是掩模厂的链，不要与晶圆 CD 混成一张图。</p><p>进机台的剂量控制若用 OCD，要防模型在换胶批次后偷偷漂：看起来 EL 变了，其实是色散表过期。SEM 抽样不足则会把局部热点平均进窗口，方向相反。两种失效都表现为「窗口会说话，硅片不认」。</p><p><span class="marginnote">散射测量的光斑通常几微米到几十微米，比 SEM 视场大、比曝光场小。它量的是垫，不是整场指纹；场内 CD 均匀性仍要另采样。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>E–D 窗口的 CD 必须声明计量链与显影/刻蚀状态。</li><li>SEM 看局部、LER、缺陷；OCD 看周期平均剖面，更快。</li><li>两种偏置来源不同，相关不是物理相等。</li><li>均值喂窗口，粗糙度与热点喂 SEM。</li><li>位置如何量，下一课。</li><li>出处：Levinson, <em>Principles of Lithography</em>；Mack 对 CD 与工艺控制的讨论。</li></ul>',12))])}const u=o(d,[["render",C]]);export{B as __pageData,u as default};
